function ficha(id){const c=id?C(id):{nome:'',vinculo:'clt',salario:0,entrada:'07:30',saida:'17:18',intervalo_min:60,dias_semana:[1,2,3,4,5],tipo_contrato:'experiencia',experiencia_dias:45,experiencia_prorrogacao:45,horas_semanais:44,endereco:{},banco:{},admissao:hoje(),ativo:true,politica_horas:'banco',dependentes_ir:0,vale_transporte:0};const e=c.endereco||{},b=c.banco||{};
 const f=(idc,rot,val,extra='')=>`<div><label for="${idc}">${rot}</label><input id="${idc}" value="${esc(val??'')}" ${extra}></div>`;
 modal(id?`Ficha · ${esc(c.nome)}`:'Nova admissão',`<div class="psficha"><h4>Dados pessoais</h4><div class="grid three" style="gap:8px">${f('fN','Nome completo *',c.nome)}${f('fCpf','CPF *',c.cpf,'inputmode="numeric"')}${f('fPis','PIS/NIS',c.pis,'inputmode="numeric"')}${f('fNasc','Nascimento *',c.nascimento,'type="date"')}
  <div><label for="fSexo">Sexo *</label><select id="fSexo"><option value=""></option>${OPT([['F','Feminino'],['M','Masculino']],c.sexo)}</select></div><div><label for="fEC">Estado civil</label><select id="fEC">${OPT([[1,'Solteiro(a)'],[2,'Casado(a)'],[3,'Divorciado(a)'],[4,'Separado(a)'],[5,'Viúvo(a)']],c.estado_civil||1)}</select></div>
  <div><label for="fRaca">Raça/cor</label><select id="fRaca">${OPT([[1,'Branca'],[2,'Preta'],[3,'Parda'],[4,'Amarela'],[5,'Indígena'],[6,'Não informado']],c.raca_cor||6)}</select></div><div><label for="fInstr">Escolaridade</label><select id="fInstr">${OPT(INSTR,c.grau_instrucao||'07')}</select></div>${f('fRg','RG',c.rg)}</div>
  <h4>Endereço e contato</h4><div class="grid three" style="gap:8px">${f('fCep','CEP',e.cep,'inputmode="numeric"')}${f('fLog','Logradouro',e.logradouro)}${f('fNum','Número',e.numero)}${f('fCompl','Complemento',e.complemento)}${f('fBairro','Bairro',e.bairro)}${f('fCid','Cidade',e.cidade)}${f('fUf','UF',e.uf,'maxlength="2"')}${f('fIbge','Código IBGE do município',e.ibge,'inputmode="numeric"')}${f('fTel','Telefone',c.telefone)}${f('fEmail','E-mail',c.email,'type="email"')}</div>
  <h4>Contrato</h4><div class="grid three" style="gap:8px"><div><label for="fVinc">Vínculo</label><select id="fVinc">${OPT(Object.entries(VINC),c.vinculo)}</select></div>${f('fAdm','Admissão *',admissaoClt(c)||c.admissao,'type="date"')}${f('fMat','Matrícula',c.matricula)}${f('fCargo','Cargo',c.cargo)}${f('fCbo','CBO',c.cbo,'inputmode="numeric" placeholder="ex.: 411005"')}${f('fDep','Departamento',c.departamento)}
  ${f('fSal','Salário (R$) *',Number(c.salario)?String(c.salario).replace('.',','):'','inputmode="decimal"')}<div><label for="fTipo">Tipo de contrato</label><select id="fTipo">${OPT([['experiencia','Experiência'],['indeterminado','Prazo indeterminado'],['determinado','Prazo determinado']],c.tipo_contrato)}</select></div><div class="row" style="gap:6px">${f('fExp','Experiência (dias)',c.experiencia_dias||45,'type="number" min="1" max="90"')}${f('fProrr','Prorrogação (dias)',c.experiencia_prorrogacao||0,'type="number" min="0" max="89"')}</div>
  ${f('fEnt','Entrada',String(c.entrada).slice(0,5),'type="time"')}${f('fSai','Saída',String(c.saida).slice(0,5),'type="time"')}${f('fInt','Intervalo (min)',c.intervalo_min,'type="number"')}${f('fHs','Horas semanais',c.horas_semanais||44,'type="number" step="0.5"')}${f('fDepIr','Dependentes para IR',c.dependentes_ir||0,'type="number" min="0"')}${f('fVt','Vale-transporte (R$/mês)',Number(c.vale_transporte)?String(c.vale_transporte).replace('.',','):'','inputmode="decimal"')}</div>
  <h4>Pagamento</h4><div class="grid three" style="gap:8px">${f('fBco','Banco',b.banco)}${f('fAg','Agência',b.agencia)}${f('fCc','Conta',b.conta)}${f('fPix','Chave PIX',c.pix)}</div>
  <p class="caption" style="margin-top:8px">Campos com * são exigidos pelo eSocial. Ao salvar a admissão CLT, o evento S-2200 fica pronto na aba eSocial.</p></div>
  <div class="modalfoot"><button data-action="close">Cancelar</button><button class="primary" data-ps-salvar="${id||''}">${id?'Salvar ficha':'Admitir'}</button></div>`);
 const cep=$('#fCep');cep.onchange=async()=>{const v=dig(cep.value);if(v.length!==8)return;try{const r=await fetch(`https://viacep.com.br/ws/${v}/json/`),j=await r.json();if(j.erro)return;$('#fLog').value=j.logradouro||'';$('#fBairro').value=j.bairro||'';$('#fCid').value=j.localidade||'';$('#fUf').value=j.uf||'';$('#fIbge').value=j.ibge||''}catch{}}}
async function salvarFicha(id){const v=s=>$(s)?.value?.trim()||'',n=s=>{const x=v(s);if(!x)return null;const y=Number(x.includes(',')?x.replace(/\./g,'').replace(',','.'):x);return Number.isFinite(y)?y:null};
 const nome=v('#fN');if(nome.length<3)return toast('Informe o nome.');if(v('#fCpf')&&!cpfOk(v('#fCpf')))return toast('CPF inválido.');const sal=n('#fSal');if(sal==null)return toast('Informe o salário.');
 const e=v('#fEnt'),s=v('#fSai'),i=Number(v('#fInt'))||0,jm=Math.max(0,(Number(s.slice(0,2))*60+Number(s.slice(3)))-(Number(e.slice(0,2))*60+Number(e.slice(3)))-i),vinc=v('#fVinc'),adm=v('#fAdm')||null;
 const row={nome,cpf:dig(v('#fCpf'))||null,pis:dig(v('#fPis'))||null,nascimento:v('#fNasc')||null,sexo:v('#fSexo')||null,estado_civil:Number(v('#fEC'))||null,raca_cor:Number(v('#fRaca'))||6,grau_instrucao:v('#fInstr'),rg:v('#fRg')||null,
  endereco:{cep:dig(v('#fCep')),logradouro:v('#fLog'),numero:v('#fNum'),complemento:v('#fCompl'),bairro:v('#fBairro'),cidade:v('#fCid'),uf:v('#fUf').toUpperCase(),ibge:dig(v('#fIbge'))},telefone:v('#fTel')||null,email:v('#fEmail')||null,
  matricula:v('#fMat')||null,cargo:v('#fCargo')||null,cbo:dig(v('#fCbo'))||null,departamento:v('#fDep')||null,tipo_contrato:v('#fTipo'),experiencia_dias:Number(v('#fExp'))||null,experiencia_prorrogacao:Number(v('#fProrr'))||0,
  entrada:e,saida:s,intervalo_min:i,jornada_min:jm||528,horas_semanais:Number(v('#fHs'))||44,dependentes_ir:Number(v('#fDepIr'))||0,vale_transporte:n('#fVt')||0,banco:{banco:v('#fBco'),agencia:v('#fAg'),conta:v('#fCc')},pix:v('#fPix')||null,updated_at:new Date().toISOString()};
 const atual=id?C(id):null;
 // Mudança programada para CLT (ex.: pró-labore até 30/09): a admissão CLT é a data da mudança; senão, a admissão do vínculo atual.
 if(atual?.proximo_em&&atual.proximo_vinculo==='clt'&&vinc==='clt'){row.proximo_em=adm;row.proximo_salario=sal}else{row.vinculo=vinc;row.salario=sal;row.admissao=adm}
 if(!id)Object.assign(row,{workspace_id:Cloud.ws,ativo:true,inicio:adm,dias_semana:[1,2,3,4,5],politica_horas:'banco'});
 const q=id?Cloud.client.from('ponto_colaboradores').update(row).eq('workspace_id',Cloud.ws).eq('id',id).select().single():Cloud.client.from('ponto_colaboradores').insert(row).select().single();const {data,error}=await q;if(error)return toast(error.message);
 await auditar(data.id,id?'Ficha alterada':'Admissão',{nome,vinculo:vinc,salario:sal,admissao:adm});closeModal();await PT().recarregar();await FL()?.garantir?.();
 const c=C(data.id);if(c&&admissaoClt(c)&&!pendenciasEsocial(c).length&&!st.eventos.some(x=>x.colaborador_id===c.id&&x.evento==='S-2200')){try{await guardarEvento('S-2200',c.id,admissaoClt(c),`Admissão de ${c.nome}`,s2200(c));toast('Ficha salva. Evento S-2200 pronto na aba eSocial.')}catch(x){toast('Ficha salva; S-2200 não gerado: '+x.message)}}else toast(pendenciasEsocial(c||{}).length?`Ficha salva. Para o eSocial ainda falta: ${pendenciasEsocial(c).join(', ')}.`:'Ficha salva.');
 await carregar(true)}

