const carregaLib=(g,src)=>window[g]?Promise.resolve():new Promise((ok,er)=>{const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=()=>er(Error('Não foi possível carregar '+g));document.head.appendChild(s)});
const tt=s=>String(s??'').normalize('NFD').replace(/[̀-ͯ]/g,'');
async function doc(titulo,blocos,nome){await carregaLib('jspdf','https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');const {jsPDF}=window.jspdf,d=new jsPDF({unit:'pt',format:'a4'}),W=595.28,M=40;let y=0;const emp=empregador();
 d.setFillColor(11,22,34);d.rect(0,0,W,70,'F');d.setTextColor(95,224,204);d.setFont('helvetica','bold');d.setFontSize(10);d.text(tt(titulo.toUpperCase()),M,28);d.setTextColor(255,255,255);d.setFontSize(13);d.text(tt(emp.razao||window.Cloud?.wsName||'Empresa'),M,48);d.setFont('helvetica','normal');d.setFontSize(9);d.text(tt(`CNPJ ${dig(emp.cnpj).replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4-$5')}`),W-M,48,{align:'right'});y=96;d.setTextColor(26,50,68);
 for(const b of blocos){if(y>770){d.addPage();y=50}if(b.h){d.setFont('helvetica','bold');d.setFontSize(11);d.text(tt(b.h),M,y);y+=16;continue}if(b.p){d.setFont('helvetica','normal');d.setFontSize(9.5);const l=d.splitTextToSize(tt(b.p),W-2*M);d.text(l,M,y);y+=l.length*12+6;continue}
  if(b.kv){d.setFontSize(9.5);for(const [k2,v] of b.kv){d.setFont('helvetica','bold');d.text(tt(k2),M,y);d.setFont('helvetica','normal');d.text(tt(v),M+170,y);y+=14}y+=4;continue}
  if(b.tab){d.setFillColor(232,242,245);d.rect(M,y-11,W-2*M,18,'F');d.setFont('helvetica','bold');d.setFontSize(9);d.text('Descricao',M+4,y+1);d.text('Ref.',330,y+1);d.text('Proventos',470,y+1,{align:'right'});d.text('Descontos',W-M-4,y+1,{align:'right'});y+=20;d.setFont('helvetica','normal');
   for(const [desc,ref,val,tp] of b.tab){d.text(tt(desc).slice(0,52),M+4,y);d.text(tt(ref||''),330,y);d.text(tp==='p'?val.toLocaleString('pt-BR',{minimumFractionDigits:2}):'',470,y,{align:'right'});d.text(tp==='d'?val.toLocaleString('pt-BR',{minimumFractionDigits:2}):'',W-M-4,y,{align:'right'});y+=14}y+=6;continue}
  if(b.ass){y=Math.max(y+30,y);d.line(M,y,M+220,y);d.line(W-M-220,y,W-M,y);d.setFontSize(8.5);d.text(tt(b.ass[0]),M,y+11);d.text(tt(b.ass[1]),W-M-220,y+11);y+=30}}
 const blob=d.output('blob'),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=nome;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}
function pdfFicha(c){const e=c.endereco||{},adm=admissaoClt(c)||c.admissao,k2=contrato(c,adm);return doc('Ficha de registro de empregado',[{h:'Identificacao'},{kv:[['Nome',c.nome],['CPF',c.cpf||'—'],['PIS/NIS',c.pis||'—'],['Nascimento',br(c.nascimento)],['RG',c.rg||'—']]},{h:'Endereco'},{kv:[['Logradouro',`${e.logradouro||''}, ${e.numero||''} ${e.complemento||''}`],['Bairro / cidade',`${e.bairro||''} · ${e.cidade||''}/${e.uf||''}`],['CEP',e.cep||'—']]},{h:'Contrato'},{kv:[['Admissao',br(adm)],['Cargo / CBO',`${c.cargo||'—'} · ${c.cbo||'—'}`],['Salario',R(k2.salario)],['Jornada',`${String(c.entrada).slice(0,5)} as ${String(c.saida).slice(0,5)}, intervalo ${c.intervalo_min} min · ${c.horas_semanais||44}h/semana`],['Tipo',c.tipo_contrato==='experiencia'?`Experiencia de ${c.experiencia_dias||45} dias${c.experiencia_prorrogacao?' + '+c.experiencia_prorrogacao:''}`:c.tipo_contrato]]},{ass:['Empregado','Empregador']}],`ficha-registro-${tt(c.nome).toLowerCase().replace(/[^a-z0-9]+/g,'-')}.pdf`)}
function pdfContrato(c){const adm=admissaoClt(c)||c.admissao,k2=contrato(c,adm),emp=empregador(),exp=c.tipo_contrato==='experiencia';return doc(exp?'Contrato de trabalho por prazo de experiencia':'Contrato individual de trabalho',[
 {p:`Pelo presente instrumento, ${emp.razao||'a EMPREGADORA'}, inscrita no CNPJ ${emp.cnpj}, com sede em ${emp.endereco||''} ${emp.municipio||''}/${emp.uf||''}, e ${c.nome}, CPF ${c.cpf||'—'}, residente em ${(c.endereco||{}).logradouro||''}, ${(c.endereco||{}).numero||''}, ${(c.endereco||{}).cidade||''}/${(c.endereco||{}).uf||''}, ajustam o presente contrato de trabalho, regido pela CLT e pelas clausulas abaixo.`},
 {p:`1. O EMPREGADO exercera a funcao de ${c.cargo||'—'} (CBO ${c.cbo||'—'}), obrigando-se a executar as atividades compativeis com a funcao, no estabelecimento da EMPREGADORA.`},
 {p:`2. A remuneracao mensal sera de ${R(k2.salario)}, paga ate o 5o dia util do mes seguinte ao vencido.`},
 {p:`3. A jornada sera de ${c.horas_semanais||44} horas semanais, das ${String(c.entrada).slice(0,5)} as ${String(c.saida).slice(0,5)}, com ${c.intervalo_min} minutos de intervalo, registrada no ponto eletronico (Jarvis Ponto). Horas excedentes serao compensadas em banco de horas ou pagas conforme a lei.`},
 ...(exp?[{p:`4. Este contrato e de experiencia, com inicio em ${br(adm)} e prazo de ${c.experiencia_dias||45} dias${c.experiencia_prorrogacao?`, prorrogavel por mais ${c.experiencia_prorrogacao} dias`:''}, nao podendo ultrapassar 90 dias (art. 445, paragrafo unico, CLT). Vencido o prazo sem manifestacao das partes, passa a vigorar por prazo indeterminado.`}]:[{p:`4. O contrato vigora por prazo indeterminado a partir de ${br(adm)}.`}]),
 {p:'5. O EMPREGADO autoriza os descontos previstos em lei (INSS, IRRF, vale-transporte) e os decorrentes de danos causados por dolo, e se compromete a cumprir o regulamento interno e a guardar sigilo das informacoes da EMPREGADORA.'},
 {p:`E, por estarem de acordo, assinam em duas vias. ${emp.municipio||''}, ${br(adm)}.`},{ass:['Empregado','Empregador']}],`contrato-${tt(c.nome).toLowerCase().replace(/[^a-z0-9]+/g,'-')}.pdf`)}
function pdfFerias(c,f){const k2=f.calculo;return doc('Aviso e recibo de ferias',[{kv:[['Empregado',c.nome],['Periodo aquisitivo',`${br(f.aquisitivo_ini)} a ${br(f.aquisitivo_fim)}`],['Gozo',`${br(f.gozo_ini)} a ${br(f.gozo_fim)} (${f.dias} dias)`],['Retorno',br(addDias(f.gozo_fim,1))],['Pagamento ate',br(f.pagamento_ate)]]},{p:'Comunicamos que as ferias serao concedidas no periodo acima (aviso com antecedencia minima de 30 dias, art. 135 da CLT).'},{tab:k2.itens},{kv:[['Liquido a receber',R(k2.liquido)]]},{ass:['Empregado','Empregador']}],`ferias-${tt(c.nome).toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${f.gozo_ini}.pdf`)}
function pdfTrct(c,r){const k2=r.calculo;return doc('Termo de rescisao do contrato de trabalho',[{kv:[['Empregado',c.nome],['CPF',c.cpf||'—'],['Admissao',br(k2.admissao)],['Desligamento',br(r.data_desligamento)],['Causa',TIPOS[r.tipo]],['Aviso previo',`${r.aviso} (${k2.aviso_dias} dias)`],['Pagamento ate',br(r.pagamento_ate)]]},{tab:k2.itens.map(i=>[i.desc,i.ref,i.valor,i.tipo])},{kv:[['Total bruto',R(k2.bruto)],['Total descontos',R(k2.descontos)],['Liquido',R(k2.liquido)],['FGTS do mes rescisorio',R(k2.fgts_mes)],[`Multa FGTS (${k2.pct_multa}%)`,R(k2.multa_fgts)]]},{p:'Recibo: declaro ter recebido as verbas rescisorias discriminadas acima.'},{ass:['Empregado','Empregador']}],`trct-${tt(c.nome).toLowerCase().replace(/[^a-z0-9]+/g,'-')}.pdf`)}

// ── Eventos ──
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ps],[data-ps-aba],[data-ps-ficha],[data-ps-docs],[data-ps-salvar],[data-ps-ferias],[data-ps-verf],[data-ps-verr],[data-ps-xml],[data-ps-pdf]');if(!b)return;const d=b.dataset;
 if(d.psAba){st.aba=d.psAba;render();return}if(d.psFicha){ficha(d.psFicha);return}if(d.psSalvar!==undefined){salvarFicha(d.psSalvar||null);return}
 if(d.psDocs){const c=C(d.psDocs);modal(`Documentos · ${esc(c.nome)}`,`<div class="row wrap" style="gap:8px"><button class="small" data-ps-pdf="ficha:${c.id}">Ficha de registro</button><button class="small" data-ps-pdf="contrato:${c.id}">Contrato de trabalho</button></div>
  <h4 style="margin-top:14px">Checklist da admissão</h4>${[['aso','Exame admissional (ASO)'],['ctps','CTPS digital conferida'],['contrato','Contrato assinado'],['vt','Termo de opção de vale-transporte'],['dependentes','Declaração de dependentes (IR/salário-família)'],['lgpd','Termo de ciência LGPD']].map(([k2,t])=>`<label class="check-l"><input type="checkbox" class="check" data-ps-chk="${k2}" ${(c.documentos||{})[k2]?'checked':''}> ${t}</label>`).join('')}
  <div class="modalfoot"><button data-action="close">Fechar</button><button class="primary" data-ps="salvarchk" data-id="${c.id}">Salvar checklist</button></div>`);return}
 if(d.psPdf){const [tipo,id]=d.psPdf.split(':'),c=C(id);try{if(tipo==='ficha')await pdfFicha(c);if(tipo==='contrato')await pdfContrato(c);if(tipo==='ferias'){const f=st.ferias.find(x=>x.id===id);await pdfFerias(C(f.colaborador_id),f)}if(tipo==='trct'){const r=st.resc.find(x=>x.id===id);await pdfTrct(C(r.colaborador_id),r)}}catch(x){toast(x.message)}return}
 if(d.psFerias){const c=C(d.psFerias),P=periodos(c).filter(p=>p.saldo>0&&p.fim<hoje()||p.estado==='em aquisição');
  modal(`Programar férias · ${esc(c.nome)}`,`<div class="grid two" style="gap:10px"><div><label for="frP">Período aquisitivo</label><select id="frP">${periodos(c).filter(p=>p.saldo>0).map(p=>`<option value="${p.ini}|${p.fim}">${br(p.ini)} a ${br(p.fim)} · saldo ${p.saldo} dias${p.estado==='em aquisição'?' (antecipação)':''}</option>`).join('')}</select></div><div><label for="frI">Início do gozo</label><input id="frI" type="date"></div>
   <div><label for="frD">Dias de gozo</label><input id="frD" type="number" min="5" max="30" value="30"></div><div><label for="frA">Abono pecuniário (vender dias)</label><input id="frA" type="number" min="0" max="10" value="0"></div></div>
   <label class="check-l" style="margin-top:8px"><input type="checkbox" class="check" id="fr13"> Adiantar 50% do 13º salário junto</label><div id="frCalc" style="margin-top:12px"></div>
   <div class="modalfoot"><button data-action="close">Cancelar</button><button class="small" data-ps="frcalc" data-id="${c.id}">Calcular</button><button class="primary" data-ps="frsalvar" data-id="${c.id}">Programar</button></div>`);return}
 if(d.psVerf){const f=st.ferias.find(x=>x.id===d.psVerf),c=C(f.colaborador_id);modal(`Férias · ${esc(c.nome)}`,`<p>Gozo de ${br(f.gozo_ini)} a ${br(f.gozo_fim)} · pagar até <b>${br(f.pagamento_ate)}</b></p>${tabela(f.calculo.itens)}<p><b>Líquido: ${R(f.calculo.liquido)}</b> · FGTS ${R(f.calculo.fgts)}</p>${(f.calculo.avisos||[]).map(a=>`<p class="notice">${esc(a)}</p>`).join('')}<div class="modalfoot"><button data-action="close">Fechar</button><button class="small" data-ps-pdf="ferias:${f.id}">Aviso e recibo (PDF)</button>${f.status==='programada'?`<button class="small" data-ps="frpagar" data-id="${f.id}">Lançar no contas a pagar</button><button class="small quiet" data-ps="frcancelar" data-id="${f.id}">Cancelar</button>`:''}</div>`);return}
 if(d.psVerr){const r=st.resc.find(x=>x.id===d.psVerr),c=C(r.colaborador_id);modal(`Rescisão · ${esc(c.nome)}`,`<p>${TIPOS[r.tipo]} em ${br(r.data_desligamento)} · pagar até <b>${br(r.pagamento_ate)}</b></p>${tabela(r.calculo.itens.map(i=>[i.desc,i.ref,i.valor,i.tipo]))}<p><b>Líquido: ${R(r.calculo.liquido)}</b> · FGTS do mês ${R(r.calculo.fgts_mes)} · multa ${r.calculo.pct_multa}% ${R(r.calculo.multa_fgts)}</p>${(r.calculo.avisos||[]).map(a=>`<p class="notice">${esc(a)}</p>`).join('')}<div class="modalfoot"><button data-action="close">Fechar</button><button class="small" data-ps-pdf="trct:${r.id}">TRCT (PDF)</button>${r.status==='calculada'?`<button class="small" data-ps="rspagar" data-id="${r.id}">Lançar no contas a pagar</button>`:''}</div>`);return}
 if(d.psXml){const {data,error}=await Cloud.client.from('esocial_eventos').select('xml,evento').eq('workspace_id',Cloud.ws).eq('id',d.psXml).single();if(error)return toast(error.message);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data.xml],{type:'application/xml'}));a.download=`${data.evento}-${d.psXml}.xml`;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500);return}
 switch(d.ps){
  case 'admitir':ficha(null);break;
  case 'salvarchk':{const docs={};document.querySelectorAll('[data-ps-chk]').forEach(x=>docs[x.dataset.psChk]=x.checked);const {error}=await Cloud.client.from('ponto_colaboradores').update({documentos:docs}).eq('workspace_id',Cloud.ws).eq('id',d.id);if(error)return toast(error.message);closeModal();toast('Checklist salvo.');await PT().recarregar();break}
  case 'empregador':{const em=empregador();modal('Dados do empregador',`<div class="grid two" style="gap:8px">${[['razao','Razão social'],['cnpj','CNPJ'],['endereco','Endereço'],['municipio','Município'],['uf','UF'],['ibge','Código IBGE do município'],['cep','CEP']].map(([k2,t])=>`<div><label>${t}<input data-emp="${k2}" value="${esc(em[k2]||'')}"></label></div>`).join('')}</div><p class="caption">Aparece nos contratos, recibos, TRCT e nos eventos do eSocial.</p><div class="modalfoot"><button data-action="close">Cancelar</button><button class="primary" data-ps="salvaremp">Salvar</button></div>`);break}
  case 'salvaremp':{const o={};document.querySelectorAll('[data-emp]').forEach(x=>o[x.dataset.emp]=x.value.trim());try{await FL().salvarParametros({empregador:o});closeModal();toast('Dados do empregador salvos.')}catch(x){toast(x.message)}break}
  case 'frcalc':case 'frsalvar':{const c=C(d.id),[ai,af]=($('#frP')?.value||'|').split('|'),ini=$('#frI').value,dias=Number($('#frD').value),ab=Number($('#frA').value)||0;if(!ai)return toast('Sem período com saldo.');if(!ini)return toast('Informe o início do gozo.');if(dias<5||dias+ab>30)return toast('Dias entre 5 e 30 (gozo + abono até 30).');
   const calc=calcFerias(c,{gozo_ini:ini,dias,abono_dias:ab,adiantar_13:$('#fr13').checked});$('#frCalc').innerHTML=`${tabela(calc.itens)}<p><b>Líquido: ${R(calc.liquido)}</b> · pagar até ${br(addDias(ini,-2))} · FGTS ${R(calc.fgts)}</p>${calc.avisos.map(a=>`<p class="notice">${esc(a)}</p>`).join('')}`;
   if(d.ps==='frcalc')break;const row={workspace_id:Cloud.ws,colaborador_id:c.id,aquisitivo_ini:ai,aquisitivo_fim:af,gozo_ini:ini,gozo_fim:addDias(ini,dias-1),dias,abono_dias:ab,adiantar_13:$('#fr13').checked,calculo:calc,pagamento_ate:addDias(ini,-2)};
   const {error}=await Cloud.client.from('folha_ferias').insert(row);if(error)return toast(error.message);await auditar(c.id,'Férias programadas',{gozo:`${ini} (${dias} dias)`,liquido:calc.liquido});closeModal();toast('Férias programadas. Gere o aviso e o recibo em PDF.');await carregar(true);break}
  case 'frcancelar':{const {error}=await Cloud.client.from('folha_ferias').update({status:'cancelada'}).eq('workspace_id',Cloud.ws).eq('id',d.id);if(error)return toast(error.message);closeModal();await carregar(true);break}
  case 'frpagar':{const f=st.ferias.find(x=>x.id===d.id),c=C(f.colaborador_id);lancarPagar(`FERIAS-${f.id.slice(0,8)}`,c,`Férias ${br(f.gozo_ini)} a ${br(f.gozo_fim)} · ${PT().curto(c.nome)}`,f.pagamento_ate,f.calculo.liquido);await Cloud.client.from('folha_ferias').update({status:'paga'}).eq('workspace_id',Cloud.ws).eq('id',f.id);closeModal();await carregar(true);break}
  case 'rescindir':{const L=colabs().filter(c=>c.ativo&&admissaoClt(c));if(!L.length)return toast('Nenhum empregado CLT ativo.');modal('Calcular rescisão',`<div class="grid two" style="gap:10px"><div><label for="rsP">Pessoa</label><select id="rsP">${L.map(c=>`<option value="${c.id}">${esc(c.nome)}</option>`).join('')}</select></div><div><label for="rsD">Data do desligamento</label><input id="rsD" type="date" value="${hoje()}"></div>
   <div><label for="rsT">Causa</label><select id="rsT">${OPT(Object.entries(TIPOS),'sem_justa_causa')}</select></div><div><label for="rsA">Aviso prévio</label><select id="rsA">${OPT([['indenizado','Indenizado'],['trabalhado','Trabalhado'],['dispensado','Dispensado'],['nao_cumprido','Não cumprido (pedido de demissão)']],'indenizado')}</select></div>
   <div><label for="rsF">Saldo do FGTS para fins rescisórios (R$)</label><input id="rsF" inputmode="decimal" placeholder="extrato da conta vinculada"></div></div><div id="rsCalc" style="margin-top:12px"></div>
   <div class="modalfoot"><button data-action="close">Cancelar</button><button class="small" data-ps="rscalc">Calcular</button><button class="primary" data-ps="rssalvar">Salvar rescisão</button></div>`);break}
  case 'rscalc':case 'rssalvar':{const c=C($('#rsP').value),fg=Number(String($('#rsF').value||'0').replace(/\./g,'').replace(',','.'))||0,r={data_desligamento:$('#rsD').value,tipo:$('#rsT').value,aviso:$('#rsA').value,saldo_fgts:fg};if(!r.data_desligamento)return toast('Informe a data.');
   const calc=calcRescisao(c,r);if(calc.erro)return toast(calc.erro);$('#rsCalc').innerHTML=`${tabela(calc.itens.map(i=>[i.desc,i.ref,i.valor,i.tipo]))}<p><b>Líquido: ${R(calc.liquido)}</b> · pagar até ${br(calc.pagamento_ate)} · FGTS do mês ${R(calc.fgts_mes)} · multa ${calc.pct_multa}% ${R(calc.multa_fgts)}</p>${calc.avisos.map(a=>`<p class="notice">${esc(a)}</p>`).join('')}`;
   if(d.ps==='rscalc')break;const {data,error}=await Cloud.client.from('folha_rescisoes').insert({workspace_id:Cloud.ws,colaborador_id:c.id,...r,calculo:calc,pagamento_ate:calc.pagamento_ate}).select().single();if(error)return toast(error.message);
   await Cloud.client.from('ponto_colaboradores').update({demissao:r.data_desligamento}).eq('workspace_id',Cloud.ws).eq('id',c.id);await auditar(c.id,'Rescisão calculada',{tipo:r.tipo,data:r.data_desligamento,liquido:calc.liquido});
   if(!pendenciasEsocial(c).length){try{await guardarEvento('S-2299',c.id,r.data_desligamento,`Desligamento de ${c.nome} (${TIPOS[r.tipo]})`,s2299(c,data,calc))}catch{}}
   closeModal();toast('Rescisão salva. Gere o TRCT e lance no contas a pagar quando for pagar.');await PT().recarregar();await carregar(true);break}
  case 'rspagar':{const r=st.resc.find(x=>x.id===d.id),c=C(r.colaborador_id);lancarPagar(`RESC-${r.id.slice(0,8)}`,c,`Rescisão ${PT().curto(c.nome)} (${TIPOS[r.tipo]})`,r.pagamento_ate,r.calculo.liquido);if(r.calculo.multa_fgts+r.calculo.fgts_mes>0)lancarPagar(`RESC-${r.id.slice(0,8)}-FGTS`,{nome:'Caixa · FGTS Digital',vinculo:'clt'},`FGTS rescisório + multa ${r.calculo.pct_multa}% · ${PT().curto(c.nome)}`,r.pagamento_ate,r.calculo.fgts_mes+r.calculo.multa_fgts);
   await Cloud.client.from('folha_rescisoes').update({status:'paga'}).eq('workspace_id',Cloud.ws).eq('id',r.id);closeModal();await carregar(true);break}
  case 'gerar1200':{const comp=$('#psComp').value,F=(FL().fechamentos()||[]).filter(f=>f.competencia===comp);let n=0,falta=[];for(const f of F){const c=C(f.colaborador_id);if(!c||!cpfOk(c.cpf)){falta.push(c?.nome||'?');continue}await guardarEvento('S-1200',c.id,comp,`Remuneração ${comp} · ${c.nome}`,s1200(c,f));
    const [y,m]=comp.split('-').map(Number);let dd=0,nn=0;while(nn<5){dd++;if(new Date(y,m,dd).getDay()!==0)nn++}await guardarEvento('S-1210',c.id,comp,`Pagamento ${comp} · ${c.nome}`,s1210(c,f,iso(new Date(y,m,dd))));n+=2}
   if(n)await guardarEvento('S-1299',null,comp,`Fechamento dos eventos periódicos ${comp}`,s1299(comp));toast(`${n+(n?1:0)} evento(s) gerados.${falta.length?' Sem CPF válido: '+falta.join(', '):''}`);await carregar(true);break}
 }});
function tabela(itens){return `<div class="tablebox"><table><tbody>${itens.map(([desc,ref,val,tp])=>`<tr><td>${esc(desc)}</td><td><small class="caption">${esc(ref||'')}</small></td><td class="num ${tp==='d'?'red':''}">${tp==='d'?'−':''}${R(val)}</td></tr>`).join('')}</tbody></table></div>`}
function lancarPagar(id,c,descricao,venc,valor){db.payables=db.payables||[];if(db.payables.some(p=>p.id===id))return toast('Já lançado no contas a pagar.');db.payables.push((window.Pagamentos?.marcar||(x=>x))({id,origem:'folha',fornecedor:c.nome,descricao:descricao+(c.pix?' · PIX '+c.pix:''),vencimento:venc,valor:r2(valor),emissao:hoje(),status:'aberto',parcela:1,parcelas:1,categoria:c.vinculo==='prolabore'?'Pró-labore':'Salários e encargos',lancadoPor:quem(),createdBy:quem()}));save();toast('Lançado no contas a pagar.')}
window.Pessoas={acessoLiberado:()=>{if(page==='pessoas')render()},periodos,calcFerias,calcRescisao};
addPage('pessoas','pessoas','Pessoas',view,'Admissão com os dados do eSocial, férias, rescisões e eventos do eSocial prontos para transmitir. Só quem criou a empresa acessa.','',()=>{});
